/* ===== src/tokens.css ===== */
/* Author: @jiuyi0204 | 未经许可禁止二次修改、二次上传、转载或重新打包。 */
@font-face {
    font-family: "Rain Page Noto Serif SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notoserifsc/notoserifsc.woff2") format("woff2");
    font-style: normal;
    font-weight: 200 900;
    font-display: swap;
}

@font-face {
    font-family: "Rain Page Cormorant";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/cormorantgaramond/cormorantgaramond.woff2") format("woff2");
    font-style: normal;
    font-weight: 300 700;
    font-display: swap;
}

@media (min-width: 701px) {
    :root {
        --rain-paper: #f4f0e7;
        --rain-paper-soft: #e9e6dc;
        --rain-paper-deep: #d8d8ca;
        --rain-ink: #26382f;
        --rain-ink-soft: #566158;
        --rain-sage: #667b68;
        --rain-sage-soft: #aeb9aa;
        --rain-mist: #cfd5cc;
        --rain-teal: #2f958b;
        --rain-line: rgba(38, 56, 47, 0.28);
        --rain-line-strong: rgba(38, 56, 47, 0.56);
        --rain-disabled: #7b847c;
        --rain-disabled-surface: #e2e5dc;
        --rain-disabled-surface-strong: #d4dbd1;
        --rain-world-choice: #dfe8dc;
        --rain-world-choice-hover: #d1dfcf;
        --rain-world-disabled-surface: #eee9df;
        --rain-code-frame: #d6e1d5;
        --rain-code-surface: #f7f5ed;
        --rain-code-text: #243a30;
        --rain-code-muted: #5b6b61;
        --rain-code-red: #8d403d;
        --rain-code-orange: #87552f;
        --rain-code-gold: #72612c;
        --rain-code-green: #45683f;
        --rain-code-teal: #286963;
        --rain-code-blue: #315f78;
        --rain-code-purple: #674e70;
        --rain-code-meta: #7d4f37;
        --rain-error: #8e4a42;
        --rain-warning: #9a7440;
        --rain-success: #4f765d;
        --rain-info: #4e6f70;
        --rain-font-body: "Rain Page Noto Serif SC", "Noto Serif SC", "Songti SC", SimSun, serif;
        --rain-font-display: "Rain Page Cormorant", "Cormorant Garamond", Georgia, serif;
        --rain-font-code: "Cascadia Mono", "SFMono-Regular", Consolas, "Liberation Mono", monospace;
        --rain-radius-sm: 0.2rem;
        --rain-radius-md: 0.65rem;
        --rain-radius-lg: 1rem;
        --rain-shadow-soft: none;
        --rain-avatar-size: 34%;
        --rain-avatar-gap: 0;
        --rain-avatar-slot: 34%;
        --topBarBlockSize: 4rem;
        --topBarIconSize: 1.2rem;
        --bottomFormBlockSize: 3rem;
        --bottomFormIconSize: 1.2rem;
        --sheldWidth: 64vw;
        --rain-fixed-cover-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/5ff27d1ba883aa89cd34403a13dfca5f96953542/assets/%E9%9B%A8%E9%A1%B5/rain-page-fixed-cover.png");
        --rain-flower-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/5ff27d1ba883aa89cd34403a13dfca5f96953542/assets/%E9%9B%A8%E9%A1%B5/rain-page-flower.png");
        --rain-raindrop-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/5ff27d1ba883aa89cd34403a13dfca5f96953542/assets/%E9%9B%A8%E9%A1%B5/rain-page-raindrop.png");
        --rain-leaf-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/5ff27d1ba883aa89cd34403a13dfca5f96953542/assets/%E9%9B%A8%E9%A1%B5/rain-page-leaf.png");
    }
}

/* ===== src/chat-layout.css ===== */
/* 雨页唯一聊天外壳：L12 横向杂志拼贴。 */
@media (min-width: 701px) {
    #chat {
        background: var(--rain-paper);
        color: var(--rain-ink);
        border-inline: 1px solid var(--rain-line);
        border-bottom: 1px solid var(--rain-line);
        box-shadow: var(--rain-shadow-soft);
        text-shadow: none;
        -ms-overflow-style: none;
        scrollbar-width: none;
    }

    #chat::-webkit-scrollbar {
        display: none;
        width: 0;
        height: 0;
    }

    #chat .mes[is_system="false"] {
        color: var(--rain-ink);
        text-shadow: none;
    }

    #chat .mes[is_user="true"] {
        display: block;
        width: 100%;
        margin: 2.2rem 0 0;
        padding: 0;
        background: var(--rain-sage);
        border-block: 1px solid var(--rain-line-strong);
    }

    #chat .mes[is_user="true"] > .mesAvatarWrapper {
        display: none;
    }

    #chat .mes[is_user="true"] > .mes_block {
        position: relative;
        width: 100%;
        min-width: 0;
        padding: 1.3rem 4.5rem 1.45rem 6.2rem;
        color: var(--rain-paper);
    }

    #chat .mes[is_user="true"] > .mes_block::before {
        content: "“";
        position: absolute;
        inset: 0.15rem auto auto 2.5rem;
        color: var(--rain-paper);
        font-family: var(--rain-font-display);
        font-size: 4.8rem;
        line-height: 1;
        opacity: 0.92;
        pointer-events: none;
    }

    #chat .mes[is_user="true"] .ch_name,
    #chat .mes[is_user="true"] .ch_name :is(.name_text, .timestamp, .mes_button) {
        color: var(--rain-paper);
        text-shadow: none;
    }

    #chat .mes[is_user="true"] .ch_name {
        margin-bottom: 0.35rem;
        border-bottom: 1px solid rgba(244, 240, 231, 0.28);
        padding-bottom: 0.35rem;
    }

    #chat .mes[is_user="false"][is_system="false"] {
        display: grid;
        grid-template-columns: minmax(0, 66fr) minmax(15rem, 34fr);
        align-items: stretch;
        width: 100%;
        margin: 0;
        padding: 0;
        background: var(--rain-paper);
        border-bottom: 1px solid var(--rain-line-strong);
    }

    #chat .mes[is_user="false"][is_system="false"] > .mes_block {
        grid-column: 1;
        grid-row: 1;
        min-width: 0;
        width: 100%;
        padding: 2.4rem 3.2rem 3.4rem;
        background: var(--rain-paper);
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
        grid-column: 2;
        grid-row: 1;
        display: flex;
        flex-direction: column;
        align-self: stretch;
        width: 100%;
        min-width: 0;
        min-height: clamp(22rem, 55dvh, 30rem);
        margin: 0;
        padding: 0;
        background: var(--rain-ink);
        border-left: 1px solid var(--rain-line-strong);
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper > .avatar {
        position: relative;
        flex: 1 1 auto;
        width: 100%;
        height: 100%;
        min-height: 0;
        margin: 0;
        border: 0;
        border-radius: 0;
        overflow: hidden;
        background: var(--rain-ink);
        cursor: default;
        pointer-events: none;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper > .avatar::before {
        content: "";
        position: absolute;
        inset: 0;
        z-index: 1;
        background-image: var(--rain-fixed-cover-image);
        background-repeat: no-repeat;
        background-position: center top;
        background-size: cover;
        pointer-events: none;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper > .avatar > img {
        display: block;
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        min-height: 0;
        object-fit: cover;
        object-position: center;
        border: 0;
        border-radius: 0;
        filter: saturate(0.72) contrast(0.92) brightness(0.8) sepia(0.08);
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper::after {
        content: "RAIN GARDEN · FIXED COVER";
        flex: 0 0 auto;
        padding: 0.65rem 0.8rem;
        color: var(--rain-paper-soft);
        background: var(--rain-ink);
        font-family: var(--rain-font-display);
        font-size: 0.68rem;
        letter-spacing: 0.12em;
        text-align: center;
        pointer-events: none;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
        color: var(--rain-paper-soft);
        background: var(--rain-ink);
        font-family: var(--rain-font-display);
        letter-spacing: 0.08em;
        text-shadow: none;
    }

    #chat .mes[is_system="true"] {
        margin: 0.9rem 1.2rem;
        padding: 0.8rem 1rem;
        color: var(--rain-ink-soft);
        background: var(--rain-paper-soft);
        border-left: 0.25rem solid var(--rain-sage);
        box-shadow: none;
    }

    #chat .ch_name {
        align-items: center;
        gap: 0.75rem;
        margin-bottom: 1rem;
        padding-bottom: 0.55rem;
        border-bottom: 1px solid var(--rain-line);
    }

    #chat .name_text {
        color: var(--rain-ink);
        font-family: var(--rain-font-body);
        font-size: 1.55em;
        font-weight: 650;
        letter-spacing: 0.08em;
    }

    #chat .timestamp {
        margin-inline-start: 0.8rem;
        color: var(--rain-ink-soft);
        font-family: var(--rain-font-display);
        font-size: 0.78em;
        letter-spacing: 0.08em;
    }

    #chat .mes_buttons,
    #chat .mes_edit_buttons,
    #chat .mes_button,
    #chat .extraMesButtons > div,
    #chat .mes_edit_buttons .menu_button,
    #chat .mes_reasoning_actions .edit_button {
        color: var(--rain-ink-soft);
        filter: none;
        text-shadow: none;
        box-shadow: none;
    }

    #chat .mes_button,
    #chat .extraMesButtons > div {
        opacity: 0.68;
    }

    #chat .mes_button:hover,
    #chat .extraMesButtons > div:hover,
    #chat .mes_edit_buttons .menu_button:hover,
    #chat .mes_reasoning_actions .edit_button:hover {
        color: var(--rain-teal);
        opacity: 1;
        filter: none;
        text-shadow: none;
        box-shadow: none;
    }

    #chat .mes_button:focus-visible,
    #chat .mes_edit_buttons .menu_button:focus-visible {
        outline: 2px solid var(--rain-teal);
        outline-offset: 3px;
    }

    #chat .mes_reasoning_details {
        margin: 0.85rem 0 1.2rem;
        color: var(--rain-ink);
        background: var(--rain-paper-soft);
        border: 1px solid var(--rain-line);
        border-radius: var(--rain-radius-sm);
        box-shadow: none;
    }

    #chat .mes_reasoning_summary {
        padding: 0.7rem 0.9rem;
        color: var(--rain-sage);
        background: transparent;
        border-bottom: 1px solid transparent;
        text-shadow: none;
    }

    #chat .mes_reasoning_details[open] .mes_reasoning_summary {
        border-bottom-color: var(--rain-line);
    }

    #chat .mes_reasoning_details :is(.mes_reasoning_header_title, .mes_reasoning_arrow, .mes_reasoning_actions, .mes_reasoning) {
        color: inherit;
        filter: none;
        text-shadow: none;
    }

    #chat .mes_reasoning {
        padding: 0.9rem 1rem 1.1rem;
    }
}

/* ===== src/full-text.css ===== */
/* T02 杂志编辑全文排版；不修正父级头像槽位。 */
@media (min-width: 701px) {
    #chat .mes_text {
        min-width: 0;
        max-width: 100%;
        color: var(--rain-ink);
        font-family: var(--rain-font-body);
        font-size: 1em;
        font-weight: 400;
        line-height: 2;
        letter-spacing: 0.035em;
        overflow-wrap: anywhere;
        text-shadow: none;
    }

    #chat .mes[is_user="true"] .mes_text {
        color: var(--rain-paper);
        font-size: 1.02em;
        line-height: 1.85;
    }

    #chat .mes_text p {
        margin: 0 0 1.15em;
    }

    #chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
        margin: 1.45em 0 0.7em;
        color: var(--rain-ink);
        font-family: var(--rain-font-display), var(--rain-font-body);
        font-weight: 600;
        line-height: 1.15;
        letter-spacing: 0.05em;
    }

    #chat .mes_text :is(strong, b) {
        color: var(--rain-sage);
        font-weight: 650;
    }

    #chat .mes_text :is(em, i) {
        color: var(--rain-ink-soft);
    }

    #chat .mes_text blockquote {
        margin: 1.4em 0;
        padding: 0.8em 1.2em;
        color: var(--rain-ink-soft);
        background: var(--rain-paper-soft);
        border: 0;
        border-left: 0.24rem solid var(--rain-sage);
    }

    #chat .mes_text hr {
        width: 52%;
        margin: 2em auto;
        border: 0;
        border-top: 1px solid var(--rain-line-strong);
        background: none;
    }

    #chat .mes_text a {
        color: var(--rain-teal);
        text-decoration-color: rgba(47, 149, 139, 0.5);
        text-underline-offset: 0.18em;
    }

    #chat .mes_text :is(ul, ol) {
        margin: 1em 0;
        padding-inline-start: 1.7em;
    }

    #chat .mes_text :is(code, pre) {
        font-family: var(--rain-font-code);
    }

    #chat .mes_text code {
        padding: 0.08em 0.32em;
        color: var(--rain-code-text);
        background: var(--rain-code-frame);
        border: 1px solid var(--rain-line);
        border-radius: var(--rain-radius-sm);
        line-height: 1.55;
        text-shadow: none;
    }

    #chat .mes_text pre {
        position: relative;
        max-width: 100%;
        overflow-x: auto;
        padding: 0.62rem;
        color: var(--rain-code-text);
        background: var(--rain-code-frame);
        border: 1px solid var(--rain-line);
        border-radius: var(--rain-radius-md);
        box-shadow: none;
        text-shadow: none;
    }

    #chat .mes_text pre code,
    #chat .mes_text pre code.hljs {
        display: block;
        width: max-content;
        min-width: 100%;
        box-sizing: border-box;
        overflow: visible;
        padding: 0.82rem 0.95rem;
        color: var(--rain-code-text);
        background: var(--rain-code-surface);
        border: 0;
        border-radius: var(--rain-radius-sm);
        line-height: 1.62;
        white-space: pre;
        box-shadow: none;
        text-shadow: none;
    }

    #chat .mes_text pre code.hljs :is(.hljs-comment, .hljs-punctuation, .hljs-subst, .hljs-tag) {
        color: var(--rain-code-muted);
    }

    #chat .mes_text pre code.hljs :is(.hljs-bullet, .hljs-deletion, .hljs-name, .hljs-selector-tag, .hljs-template-variable, .hljs-variable) {
        color: var(--rain-code-red);
    }

    #chat .mes_text pre code.hljs :is(.hljs-attr, .hljs-link, .hljs-literal, .hljs-number, .hljs-symbol, .hljs-variable.constant_) {
        color: var(--rain-code-orange);
    }

    #chat .mes_text pre code.hljs :is(.hljs-class .hljs-title, .hljs-title, .hljs-title.class_, .hljs-strong) {
        color: var(--rain-code-gold);
    }

    #chat .mes_text pre code.hljs :is(.hljs-addition, .hljs-code, .hljs-string, .hljs-title.class_.inherited__) {
        color: var(--rain-code-green);
    }

    #chat .mes_text pre code.hljs :is(.hljs-built_in, .hljs-doctag, .hljs-keyword.hljs-atrule, .hljs-quote, .hljs-regexp) {
        color: var(--rain-code-teal);
    }

    #chat .mes_text pre code.hljs :is(.hljs-attribute, .hljs-function .hljs-title, .hljs-section, .hljs-title.function_, .ruby .hljs-property) {
        color: var(--rain-code-blue);
    }

    #chat .mes_text pre code.hljs :is(.hljs-emphasis, .hljs-keyword, .hljs-template-tag, .hljs-type) {
        color: var(--rain-code-purple);
    }

    #chat .mes_text pre code.hljs :is(.hljs-meta, .hljs-meta .hljs-keyword, .hljs-meta .hljs-string) {
        color: var(--rain-code-meta);
    }

    #chat .mes_text pre .code-copy {
        color: var(--rain-ink-soft);
        background: var(--rain-paper);
        border: 1px solid var(--rain-line);
        border-radius: var(--rain-radius-sm);
        opacity: 1;
        filter: none;
        box-shadow: none;
        text-shadow: none;
    }

    #chat .mes_text pre .code-copy:hover {
        color: var(--rain-teal);
        background: var(--rain-code-frame);
        opacity: 1;
    }

    #chat .mes_text pre .code-copy:focus-visible {
        outline: 2px solid var(--rain-teal);
        outline-offset: 1px;
    }

    #chat .mes_text table {
        display: block;
        max-width: 100%;
        overflow-x: auto;
        border-collapse: collapse;
    }

    #chat .mes_text :is(th, td) {
        padding: 0.55em 0.75em;
        border: 1px solid var(--rain-line);
    }

    #chat .mes_text th {
        color: var(--rain-paper);
        background: var(--rain-sage);
    }

    #chat .mes_text img,
    #chat .mes_media_wrapper img {
        max-width: 100%;
        height: auto;
        border: 1px solid var(--rain-line);
        box-shadow: none;
    }
}

/* ===== src/windows/controls.css ===== */
/* 各窗口共享控件语言；仅限列出的稳定窗口根。 */
@media (min-width: 701px) {
    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select) {
        color: var(--rain-ink);
        background: var(--rain-paper-soft);
        border: 1px solid var(--rain-line-strong);
        border-radius: var(--rain-radius-sm);
        font-family: var(--rain-font-body);
        box-shadow: none;
        text-shadow: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(input, textarea, select):focus-visible {
        outline: 2px solid var(--rain-teal);
        outline-offset: 1px;
        border-color: var(--rain-teal);
        box-shadow: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(option, optgroup) {
        color: var(--rain-ink);
        background: var(--rain-paper);
        font-family: var(--rain-font-body);
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(input[type="checkbox"], input[type="radio"]) {
        accent-color: var(--rain-sage);
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    input[type="range"] {
        accent-color: var(--rain-sage);
        filter: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(.menu_button, button):not(.fa-solid):not(.fa-regular) {
        color: var(--rain-ink);
        background: var(--rain-paper-soft);
        border-color: var(--rain-line-strong);
        font-family: var(--rain-font-body);
        box-shadow: none;
        text-shadow: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(.menu_button, button):hover {
        color: var(--rain-teal);
        border-color: var(--rain-teal);
        filter: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(input, textarea, select, button, .menu_button):disabled {
        color: var(--rain-disabled);
        background-color: var(--rain-disabled-surface);
        border-color: var(--rain-line);
        opacity: 1;
        filter: none;
        text-shadow: none;
        box-shadow: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    :is(.menu_button.disabled, button.disabled, input[aria-disabled="true"], textarea[aria-disabled="true"], select[aria-disabled="true"], button[aria-disabled="true"], [role="button"][aria-disabled="true"]) {
        color: var(--rain-disabled);
        background-color: var(--rain-disabled-surface);
        border-color: var(--rain-line);
        opacity: 1;
        filter: none;
        text-shadow: none;
        box-shadow: none;
    }

    :is(#left-nav-panel, #rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #rm_extensions_block, #PersonaManagement, #right-nav-panel, #completion_prompt_manager, #completion_prompt_manager_popup)
    select option:disabled {
        color: var(--rain-disabled);
