/* ===== src/windows/transient.css ===== */
/* W13 弹窗、通知、菜单与语义状态。 */
@media (min-width: 701px) {
    :is(.popup, .popup-content, dialog.popup, #dialogue_popup) {
        color: var(--rain-ink);
        background: var(--rain-paper);
        border-color: var(--rain-line-strong);
        box-shadow: var(--rain-shadow-soft);
        text-shadow: none;
    }

    :is(.popup, .popup-content, dialog.popup, #dialogue_popup) :is(h1, h2, h3, h4) {
        color: var(--rain-ink);
        font-family: var(--rain-font-body);
        border-bottom: 1px solid var(--rain-line);
        text-shadow: none;
    }

    #toast-container > .toast {
        width: min(20rem, calc(100vw - 2rem));
        min-height: 0;
        margin: 0 0 0.35rem;
        padding: 0.55rem 0.75rem 0.6rem 0.9rem;
        color: var(--rain-ink) !important;
        background-color: var(--rain-paper) !important;
        background-image: none !important;
        border: 1px solid var(--rain-line-strong);
        border-left-width: 0.24rem;
        border-radius: var(--rain-radius-sm);
        box-shadow: none !important;
        filter: none !important;
        opacity: 1 !important;
        text-shadow: none !important;
    }

    #toast-container > .toast:hover {
        box-shadow: none !important;
        filter: none !important;
    }

    #toast-container > .toast-info { border-left-color: var(--rain-info); }
    #toast-container > .toast-warning { border-left-color: var(--rain-warning); }
    #toast-container > .toast-error { border-left-color: var(--rain-error); }
    #toast-container > .toast-success { border-left-color: var(--rain-success); }

    #toast-container :is(.toast-title, .toast-message, .toast-close-button) {
        color: var(--rain-ink) !important;
        text-shadow: none !important;
    }

    #toast-container .toast-title {
        font-size: 0.9em;
        line-height: 1.25;
    }

    #toast-container .toast-message {
        font-size: 0.78em;
        line-height: 1.3;
    }

    #toast-container .toast-progress {
        height: 2px;
        background: var(--rain-sage);
        opacity: 0.75;
    }

    :is(#context-menu, .options-content, .list-group) {
        color: var(--rain-ink);
        background: var(--rain-paper);
        border-color: var(--rain-line-strong);
        box-shadow: var(--rain-shadow-soft);
        text-shadow: none;
    }

    :is(#context-menu, .options-content, .list-group) :is(a, button, .list-group-item) {
        color: var(--rain-ink);
        background: transparent;
        opacity: 1;
        filter: none;
        text-shadow: none;
    }

    :is(#context-menu, .options-content, .list-group) :is(a, button, .list-group-item):hover {
        color: var(--rain-paper);
        background: var(--rain-sage);
    }

    :is(.warning, .redWarningBG, .neutral_warning) {
        background-image: none;
        background-repeat: no-repeat;
        box-shadow: none;
        text-shadow: none;
    }
}

